import{Link}from"react-router-dom";import type{VendorProduct}from"../../types/vendor";import VendorProductStatusBadge from"./VendorProductStatusBadge";const money=(n:number)=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(n);export default function VendorProductTable({products,busy,onArchive}:{products:VendorProduct[];busy:boolean;onArchive:(id:number)=>void}){return <div className="overflow-x-auto rounded-xl border bg-white"><table className="w-full text-left text-sm"><thead className="bg-slate-100"><tr><th className="p-4">Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th className="p-4">Actions</th></tr></thead><tbody>{products.map(p=><tr className="border-t" key={p.id}><td className="p-4"><div className="flex items-center gap-3">{p.imageUrl?<img alt="" className="h-12 w-12 rounded object-cover" src={p.imageUrl}/>:<div className="h-12 w-12 rounded bg-slate-100"/>}<strong>{p.name}</strong></div></td><td>{p.categoryName}</td><td>{money(p.price)}</td><td>{p.stockQuantity}</td><td><VendorProductStatusBadge status={p.status}/></td><td className="space-x-3 p-4"><Link className="text-brand-700 underline" to={`/vendor/products/${p.id}/edit`}>Edit</Link>{p.status!=="ARCHIVED"&&<button className="text-red-700 underline" disabled={busy} onClick={()=>onArchive(p.id)}>Archive</button>}</td></tr>)}</tbody></table></div>}
